import { type NextRequest, NextResponse } from 'next/server'
import { updateSession } from '@/lib/supabase/middleware'
import { createServerClient } from '@supabase/ssr'
import type { Database } from '@/lib/supabase/types'

/**
 * In-memory domain → slug cache. TTL 60s to prevent DB round-trips for every request.
 * Host-header attackers varying Host cannot spin up unbounded DB queries (#87).
 */
const domainCache = new Map<string, { slug: string | null; expiresAt: number }>()
const DOMAIN_CACHE_TTL_MS = 60_000

async function resolveCustomDomain(
  host: string,
  cookies: ReturnType<NextRequest['cookies']['getAll']>,
): Promise<string | null> {
  const cached = domainCache.get(host)
  if (cached && Date.now() < cached.expiresAt) {
    return cached.slug
  }

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() { return cookies },
        setAll() {},
      },
    },
  )

  const { data: studio } = await supabase
    .from('studios')
    .select('slug')
    .eq('custom_domain', host)
    .eq('custom_domain_verified', true)
    .eq('white_label_enabled', true)
    .maybeSingle()

  const slug = studio?.slug ?? null
  domainCache.set(host, { slug, expiresAt: Date.now() + DOMAIN_CACHE_TTL_MS })
  return slug
}

/**
 * Next.js 16 middleware — renamed from middleware.ts to proxy.ts.
 *
 * Runs on every matched request to:
 * 1. Handle custom domain rewrites (verified domains only — host header attack prevention)
 * 2. Refresh the Supabase session.
 * 3. Redirect unauthenticated requests to protected routes → /login.
 */
export async function proxy(request: NextRequest) {
  const host = request.headers.get('host') ?? ''
  const appHost = new URL(process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000').host

  // Custom domain rewrite — only runs when the host is NOT the primary app host.
  // Domain lookup is cached in memory for 60s to prevent DB DoS via Host header (#87).
  if (host && host !== appHost && !host.startsWith('localhost')) {
    const slug = await resolveCustomDomain(host, request.cookies.getAll())

    if (slug) {
      const url = request.nextUrl.clone()
      // Rewrite to the public booking page for this studio
      url.pathname = `/book/${slug}${url.pathname === '/' ? '' : url.pathname}`
      return NextResponse.rewrite(url)
    }

    // Domain not found or not verified — return 404 to prevent info leakage
    if (!host.endsWith(`.${appHost}`)) {
      return new NextResponse('Not found', { status: 404 })
    }
  }

  return updateSession(request)
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static files)
     * - _next/image (image optimization)
     * - favicon.ico
     * - public folder files
     * - api/webhooks (webhook endpoints must not have session refresh overhead)
     * - api/health (Railway healthcheck — must bypass custom-domain + session logic, Host header doesn't match appHost)
     */
    '/((?!_next/static|_next/image|favicon.ico|api/webhooks|api/health|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|css|js)$).*)',
  ],
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'
import type { Database } from './types'

/**
 * Updates the session on every request to prevent session expiry.
 *
 * CRITICAL: This function rewrites cookies on BOTH the request (for downstream
 * reads in the same request cycle) AND the response (for the browser to send
 * the updated session token on the next request).
 *
 * This is the Next.js 16 pattern — proxy.ts calls this, not middleware.ts.
 */
export async function updateSession(request: NextRequest) {
  // Inject x-pathname header so server components (layouts) can read the
  // current pathname via `headers()`. Consumed by lib/breadcrumbs/resolve.ts.
  const requestHeaders = new Headers(request.headers)
  requestHeaders.set('x-pathname', request.nextUrl.pathname)

  let supabaseResponse = NextResponse.next({ request: { headers: requestHeaders } })

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          // Write on the request so downstream server components can read it
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          // Rebuild the response with the updated request cookies + pathname header
          supabaseResponse = NextResponse.next({ request: { headers: requestHeaders } })
          // Write on the response so the browser stores the refreshed token
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  // IMPORTANT: Always use getUser() — never getSession() for auth checks.
  // getUser() validates the JWT against the Supabase server.
  const {
    data: { user },
  } = await supabase.auth.getUser()

  const path = request.nextUrl.pathname

  // Redirect unauthenticated users away from protected routes
  if (!user) {
    const isProtected =
      path.startsWith('/dashboard') ||
      path.startsWith('/calendar') ||
      path.startsWith('/appointments') ||
      path.startsWith('/waitlist') ||
      path.startsWith('/clients') ||
      path.startsWith('/forms') ||
      path.startsWith('/ai-design') ||
      path.startsWith('/artists') ||
      path.startsWith('/guest-artists') ||
      path.startsWith('/inventory') ||
      path.startsWith('/commissions') ||
      path.startsWith('/payroll') ||
      path.startsWith('/payments') ||
      path.startsWith('/locations') ||
      path.startsWith('/marketing') ||
      path.startsWith('/settings') ||
      path.startsWith('/admin')

    if (isProtected) {
      const redirectUrl = request.nextUrl.clone()
      redirectUrl.pathname = '/login'
      redirectUrl.searchParams.set('redirectedFrom', path)
      return NextResponse.redirect(redirectUrl)
    }

    return supabaseResponse
  }

  // Onboarding redirect disabled temporarily — will re-enable later.
  // Authenticated users go straight through to the app.

  return supabaseResponse
}

