export const metadata: Metadata = {
  title: 'Clients — InkOS',
}

export default async function ClientsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // S23 audit v1 — Clients page is the client list only. Tags moved to
  // /settings/tags, Consent Forms live in the sidebar, AI Design lives on
  // the individual client profile (or /ai-design).
  const [clientsResult, tagsResult] = await Promise.all([
    supabase
      .from('clients')
      .select(CLIENT_LIST_SELECT)
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(CLIENT_LIST_PAGE_SIZE),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
  ])
  const initialClients = (clientsResult.data ?? []) as unknown as Database['public']['Tables']['clients']['Row'][]
  const tagLibrary = (tagsResult.data ?? []) as ClientTag[]

  return (
    <Page title="Clients">
      {/*
        The "+ New client" primary CTA lives inside ClientsPageClient because it
        opens a state-owned drawer. When we migrate to the ContextualSaveBar +
        shared drawer-provider pattern in Phase 2, lift it into `primaryAction`.
      */}
      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
        <ClientsPageClient
          initialClients={initialClients}
          tagLibrary={tagLibrary}
        />
      </Suspense>
    </Page>
  )
}

